          "code": "import torch, torch.nn as nn, torch.nn.functional as F\n\ndef double_conv(cin, cout):\n    return nn.Sequential(\n        nn.Conv2d(cin, cout, 3, padding=1), nn.BatchNorm2d(cout), nn.ReLU(inplace=True),\n        nn.Conv2d(cout, cout, 3, padding=1), nn.BatchNorm2d(cout), nn.ReLU(inplace=True))\n\nclass UNet(nn.Module):\n    def __init__(self, in_ch=3, n_classes=2, chs=(64, 128, 256, 512)):\n        super().__init__()\n        self.downs = nn.ModuleList()\n        c = in_ch\n        for ch in chs:                                   # encoder\n            self.downs.append(double_conv(c, ch)); c = ch\n        self.bottleneck = double_conv(chs[-1], chs[-1] * 2)\n        self.ups, self.up_convs = nn.ModuleList(), nn.ModuleList()\n        for ch in reversed(chs):                          # decoder\n            self.ups.append(nn.ConvTranspose2d(ch * 2, ch, kernel_size=2, stride=2))\n            self.up_convs.append(double_conv(ch * 2, ch))  # ch (upsampled) + ch (skip)\n        self.head = nn.Conv2d(chs[0], n_classes, 1)        # 1x1 = per-pixel classifier\n\n    def forward(self, x):\n        skips = []\n        for down in self.downs:\n            x = down(x); skips.append(x); x = F.max_pool2d(x, 2)\n        x = self.bottleneck(x)\n        for up, conv, skip in zip(self.ups, self.up_convs, reversed(skips)):\n            x = up(x)\n            if x.shape[-2:] != skip.shape[-2:]:            # size guard (odd dims)\n                x = F.interpolate(x, size=skip.shape[-2:], mode='nearest')\n            x = conv(torch.cat([skip, x], dim=1))          # THE skip: concat, then convolve\n        return self.head(x)\n\nnet = UNet()\nprint(net(torch.randn(1, 3, 256, 256)).shape)             # torch.Size([1, 2, 256, 256])\nprint(f'{sum(p.numel() for p in net.parameters())/1e6:.1f}M params')   # ~31.0M params",
